  for j in range(1,n+1):
   yy,xx=np.where(lab==j)
   if len(xx)>8: print(name,len(xx),'center',np.round([xx.mean(),yy.mean()],2),'bbox',[xx.min(),yy.min(),xx.max(),yy.max()])
